<template>
  <sf-sheet class="context-subscription" :open="!!gate" contained :resizable="false" :busy="processing" :title="heading" @input="$emit('close')">
    <template v-if="gate">
      <div class="context-purchase-target"><span class="context-purchase-icon"><sf-icon :name="gate.kind==='usage'||gate.kind==='unknown'?'coach':'membership'" :size="22"/></span><div><small>{{ gate.context.label }}</small><strong>{{ gate.context.resourceName }}</strong><span v-if="gate.context.detail">{{ gate.context.detail }}</span><p v-if="gate.context.draft&&gate.stage!=='success'&&gate.kind!=='usage'" class="context-purchase-snippet">{{ gate.context.draft }}</p></div></div>
      <template v-if="gate.stage==='success'"><p class="context-purchase-copy">{{ gate.kind==='unknown'?'Your allowance is available. Your saved message is ready to send.':gate.context.action==='send-message'?'Your Premium membership is active and your new conversation allowance is ready. Your message is still here.':gate.context.success }}</p><div v-if="gate.context.draft" class="context-purchase-draft"><small>YOUR MESSAGE</small><p>{{ gate.context.draft }}</p></div><p class="context-purchase-hint">{{ gate.context.action==='send-message'?'Nothing has been sent yet. Send your saved message when you’re ready.':'Continue when you’re ready. Your original selection has been kept.' }}</p></template>
      <template v-else-if="gate.stage==='failure'||gate.stage==='cancelled'"><p class="context-purchase-copy">{{ gate.stage==='failure'?'The subscription could not be completed. Your membership and allowance have not changed.':'The purchase was canceled. Your membership and allowance have not changed.' }}</p><p class="context-purchase-hint">Your selection{{ gate.context.draft?' and message are':' is' }} still here. You can try again or return to what you were doing.</p></template>
      <template v-else-if="gate.stage==='pending'"><p class="context-purchase-copy">Your purchase is still being confirmed. We’ll unlock Premium and add your allowance after confirmation.</p><p class="context-purchase-hint">You don’t need to buy again. Your original activity has been kept.</p></template>
      <template v-else-if="gate.stage==='event-closed'"><p class="context-purchase-copy">Registration for this challenge is no longer open. Your Premium membership is active and you have not been entered into the event.</p><p class="context-purchase-hint">Check the event dates or explore another challenge.</p></template>
      <template v-else-if="gate.stage==='access-error'"><p class="context-purchase-copy">Premium is active, but we couldn’t open your selected activity. Your subscription is kept. Return to the page to check its availability.</p></template>
      <template v-else-if="gate.kind==='usage'&&member.active"><p class="context-purchase-copy">Your Premium membership is still active. Your current conversation allowance is used up.</p><p v-if="member.resetAt" class="context-purchase-hint">New allowance is available {{ date(member.resetAt) }}.</p><p v-else class="context-purchase-hint">New allowance is not available yet. You can still read saved conversations and use your training benefits.</p><div v-if="gate.context.draft" class="context-purchase-draft"><small>SAVED MESSAGE</small><p>{{ gate.context.draft }}</p></div></template>
      <template v-else-if="gate.kind==='unknown'"><p class="context-purchase-copy">We couldn’t confirm your conversation allowance. Your message is saved. Check again before sending.</p><p class="context-purchase-hint">This does not mean you need another subscription.</p></template>
      <template v-else>
        <sf-badge v-if="gate.expired" tone="warning">Premium expired</sf-badge>
        <p class="context-purchase-copy">{{ gate.body }}</p>
        <ul v-if="gate.context.kind!=='membership'" class="context-purchase-benefits"><li v-for="benefit in gate.benefits" :key="benefit"><sf-icon name="check" :size="16"/>{{ benefit }}</li></ul>
        <section class="context-premium-overview" aria-label="Complete Premium benefits"><p class="context-premium-eyebrow">ONE PREMIUM MEMBERSHIP</p><h3>{{ gate.context.kind==='membership'?'Everything for your next step':'And more for the way you train' }}</h3><div v-for="benefit in benefitGroups" :key="benefit.title" class="context-premium-benefit"><sf-icon :name="benefit.icon" :size="19"/><div><h4>{{ benefit.title }}</h4><p>{{ benefit.description }}</p></div></div><p class="context-premium-allowance">Your first subscription adds new conversation allowance immediately. Unlimited conversations apply only during eligible limited-time events.</p></section>
        <p v-if="!offers.length" class="context-purchase-hint">Subscription options are temporarily unavailable. Please try again later.</p>
      </template>
    </template>
    <template #footer>
      <div v-if="gate&&gate.kind==='membership'&&['offer','processing'].includes(gate.stage)" class="context-purchase-offers context-purchase-offers--fixed" role="radiogroup" aria-label="Subscription billing period"><button v-for="offer in offers" :key="offer.sku.id" type="button" role="radio" :aria-checked="selectedId===offer.sku.id?'true':'false'" :disabled="processing" @click="selectedId=offer.sku.id"><span class="context-purchase-period"><span class="context-purchase-radio"></span><strong>{{ offer.sku.billingPeriod==='annual'?'Yearly':'Monthly' }}</strong></span><span class="context-purchase-price"><strong>{{ money(offer.sku.priceCents,offer.sku.currency) }}</strong><small>{{ offer.sku.billingPeriod==='annual'?' / year':' / month' }}</small></span><small>{{ offer.sku.billingPeriod==='annual'&&annualSaving>0?'Save '+annualSaving+'% vs monthly':'Same Premium benefits' }}</small></button></div>
      <p v-if="gate&&gate.kind==='membership'&&['offer','processing'].includes(gate.stage)&&selectedOffer" class="context-purchase-renewal">{{ money(selectedOffer.sku.priceCents,selectedOffer.sku.currency) }} charged today, then {{ selectedOffer.sku.billingPeriod==='annual'?'yearly':'monthly' }}. Auto-renews until canceled in your store subscription settings.</p>
      <sf-button v-if="gate&&gate.stage==='success'" @click="$emit('resume')">{{ gate.context.continueLabel }}</sf-button>
      <sf-button v-else-if="gate&&['failure','cancelled'].includes(gate.stage)" @click="$emit('retry')">Back to plans</sf-button>
      <sf-button v-else-if="gate&&gate.stage==='pending'" @click="$emit('check')">Check purchase status</sf-button>
      <sf-button v-else-if="gate&&['access-error','event-closed'].includes(gate.stage)" @click="$emit('close')">Back to your activity</sf-button>
      <sf-button v-else-if="gate&&gate.kind==='unknown'" :disabled="processing" @click="$emit('refresh')">{{ processing?'Checking allowance…':'Check allowance again' }}</sf-button>
      <sf-button v-else-if="gate&&gate.kind==='usage'&&member.active" @click="$emit('close')">Back to conversation</sf-button>
      <sf-button v-else :disabled="!selectedOffer||processing" @click="$emit('purchase',selectedOffer)">{{ processing?'Confirming purchase…':selectedOffer?'Subscribe · '+money(selectedOffer.sku.priceCents,selectedOffer.sku.currency)+(selectedOffer.sku.billingPeriod==='annual'?' / year':' / month'):'Plans unavailable' }}</sf-button>
      <button v-if="gate&&!processing" type="button" class="context-purchase-dismiss" @click="gate.kind==='usage'&&member.active?$emit('usage'):$emit('close')">{{ gate.kind==='usage'&&member.active?'View Membership & Usage':gate.stage==='success'?'Stay here':gate.stage==='pending'?'Return while we confirm':gate.context.cancelLabel }}</button>
    </template>
  </sf-sheet>
</template>
<script>
import {SfSheet,SfButton,SfBadge,SfIcon} from '@/design-system'
import {membershipDate} from './membership-view'
import {premiumBenefitGroups} from './premium-benefits'
export default {components:{SfSheet,SfButton,SfBadge,SfIcon},props:{gate:Object,member:Object,offers:{type:Array,default:()=>[]}},data(){return{selectedId:'',benefitGroups:premiumBenefitGroups}},computed:{processing(){return ['processing','refreshing'].includes(this.gate?.stage)},selectedOffer(){return this.offers.find(o=>o.sku.id===this.selectedId)},annualSaving(){const monthly=this.offers.find(o=>o.sku.billingPeriod==='monthly')?.sku,annual=this.offers.find(o=>o.sku.billingPeriod==='annual')?.sku;return monthly?.priceCents>0&&annual&&monthly.currency===annual.currency?Math.floor((1-annual.priceCents/(12*monthly.priceCents))*100):0},heading(){if(!this.gate)return '';return {success:'You’re ready to continue',failure:'Purchase not completed',cancelled:'Purchase canceled',pending:'Confirming your purchase','access-error':'This item is unavailable','event-closed':'Challenge registration is closed'}[this.gate.stage]||this.gate.title}},watch:{'gate.context.key':{immediate:true,handler(){this.selectedId=(this.offers.find(o=>o.sku.billingPeriod==='monthly')||this.offers[0])?.sku.id||''}}},methods:{date:membershipDate,money(cents,currency){return new Intl.NumberFormat('en-US',{style:'currency',currency}).format(cents/100)}}}
</script>
